<script setup>
import {Head,Link,useForm} from '@inertiajs/vue3';import CustomerShell from '../../Components/CustomerShell.vue';const props=defineProps({email:String,token:String});const form=useForm({email:props.email??'',token:props.token??'',password:'',password_confirmation:''});const submit=()=>form.post('/reset-password',{onFinish:()=>form.reset('password','password_confirmation')});
</script><template><Head title="Kata sandi baru"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">Keamanan akun</p><h1>Kata sandi baru</h1><p>Gunakan minimal 12 karakter.</p><div class="grid gap-3"><label class="text-[10px] font-semibold text-white/70">Email<input v-model="form.email" type="email" required></label><label class="text-[10px] font-semibold text-white/70">Kata sandi baru<input v-model="form.password" type="password" minlength="12" required></label><label class="text-[10px] font-semibold text-white/70">Ulangi kata sandi<input v-model="form.password_confirmation" type="password" required></label><button class="lf-primary w-full" :disabled="form.processing">Simpan</button></div><div class="lf-auth-links justify-end"><Link href="/login">Kembali ke masuk</Link></div></form></main></CustomerShell></template>